import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { startProductServer } from '../../site/scripts/wasm-browser.mjs';
import { launchBrowser } from '../../site/scripts/browser-support.mjs';
const root=process.cwd();
const files=new Map();
for(const mode of ['baseline','current']){
 const dir=join(root,mode==='baseline'?'target/compilation-startup/baseline/source':'target/wasm-browser/source');
 for(const name of ['kagari_web.js','kagari_web_bg.wasm']) files.set(`${mode}/${name}`,await readFile(join(dir,name)));
}
files.set('browser-basic.kbc',await readFile(join(root,'target/fixtures/browser-basic.kbc')));
const server=await startProductServer({files});const attempts=[];const {browser,executablePath}=await launchBrowser(undefined,attempts);
const results={browser:browser.version(),executablePath,attempts,samples:[]};
const workloads={minimal:'fn main()->i32{42}',trait:'pub trait Echo<T> { fn get(self) -> T; } pub struct Pair { val number: i32 } impl Echo<i32> for Pair { fn get(self) -> i32 { self.number } } fn read<U: Echo<i32>>(value: U) -> i32 { value.get() } fn main() -> i32 { read(Pair { number: 42 }) }'};
try{
 for(const [workload,source] of Object.entries(workloads))for(let sample=0;sample<5;sample++)for(const mode of ['baseline','current']){
  const context=await browser.newContext({viewport:{width:1280,height:900}});const page=await context.newPage();await page.goto(`${server.origin}/kagari/wasm/`);
  const result=await page.evaluate(async({mode,source})=>{
   const get=(s)=>JSON.parse(s);const assert=(yes,message)=>{if(!yes)throw new Error(message)};
   let t=performance.now();const api=await import(`/kagari/wasm/${mode}/kagari_web.js`);const wasm=await api.default();const initializationMs=performance.now()-t;
   const memory=()=>wasm.memory.buffer.byteLength;
   const out={initializationMs,memoryAfterInit:memory(),sessions:[]};
   function run(session,label){
    let t=performance.now();let text=session.compile(source);const compileMs=performance.now()-t;let r=get(text);assert(r.status==='ready',text);const memoryAfterCompile=memory();
    t=performance.now();r=get(session.start());let slices=0;while(r.status==='runnable'&&slices++<1000)r=get(session.drive(1000));const firstMs=performance.now()-t;assert(r.status==='complete'&&r.result?.tag==='i32'&&r.result.value==='42',JSON.stringify(r));
    t=performance.now();r=get(session.start());slices=0;while(r.status==='runnable'&&slices++<1000)r=get(session.drive(1000));const repeatMs=performance.now()-t;assert(r.status==='complete'&&r.result?.value==='42',JSON.stringify(r));
    t=performance.now();r=get(session.reset());const resetMs=performance.now()-t;assert(r.status==='idle',JSON.stringify(r));return {label,compileMs,firstMs,repeatMs,resetMs,memoryAfterCompile,memoryAfterReset:memory()};
   }
   for(const label of ['first','second']){
    t=performance.now();const session=new api.BrowserSession();const constructionMs=performance.now()-t;
    const item={constructionMs,...run(session,label)};out.sessions.push(item);
    if(label==='second')out.sessions.push({constructionMs:0,...run(session,'retained')});
    t=performance.now();session.free();item.freeMs=performance.now()-t;item.memoryAfterFree=memory();
   }
   const bytes=new Uint8Array(await(await fetch('/kagari/wasm/browser-basic.kbc')).arrayBuffer());const external=new api.BrowserSession();t=performance.now();const loaded=get(external.load_artifact(bytes));out.externalLoadMs=performance.now()-t;assert(loaded.status==='ready',JSON.stringify(loaded));t=performance.now();let r=get(external.start());let slices=0;let output=[];while(r.status==='runnable'&&slices++<1000){r=get(external.drive(1000));output.push(...r.output)}out.externalFirstMs=performance.now()-t;assert(r.status==='complete',JSON.stringify(r));out.externalResult=r.result;out.externalOutput=output;external.free();out.memoryFinal=memory();return out;
  },{mode,source});
  results.samples.push({mode,workload,sample,...result});await context.close();
  await writeFile(join(root,'target/compilation-startup/browser-results.json'),JSON.stringify(results,null,2));
  console.log(JSON.stringify({mode,workload,sample,first:result.sessions[0].compileMs,total:result.sessions[0].constructionMs+result.sessions[0].compileMs,retained:result.sessions[2].compileMs}));
 }
}finally{await browser.close();await server.close()}

