use kagari::{engine::{KagariEngine, source::CheckedModule}, program::PreparedProgram, BytecodeArtifact};
use kagari_source::{source::SourceFile, source_database::SourceLayer};
use kagari_common::identity::{ModuleIdentity,PackageId};
use kagari_runtime::{module::entry::ProgramEntry,value::Value};
use kagari_contract::types::PublicItem;
use kagari_types::ty::Ty;
use std::time::Instant;

const TRAIT: &str = "pub trait Echo<T> { fn get(self) -> T; } pub struct Pair { val number: i32 } impl Echo<i32> for Pair { fn get(self) -> i32 { self.number } } fn read<U: Echo<i32>>(value: U) -> i32 { value.get() } fn main() -> i32 { read(Pair { number: 42 }) }";
fn millis(start: Instant) -> f64 { start.elapsed().as_secs_f64()*1000.0 }
fn prepare(engine:&KagariEngine, checked:&CheckedModule) -> PreparedProgram { PREPARE_BODY }
fn nodes(ty:&Ty)->usize {
    1+match ty {
        Ty::Builtin(_) | Ty::Host(_) | Ty::SelfType(_) | Ty::Parameter{..}=>0,
        Ty::Reference{target,..} | Ty::Range(target,_) | Ty::Iter(target) | Ty::Array(target) | Ty::Set(target,_)=>nodes(target),
        Ty::Map{key,value,..}=>nodes(key)+nodes(value),
        Ty::Tuple(items)=>items.iter().map(nodes).sum(),
        Ty::Function{params,result}=>params.iter().map(nodes).sum::<usize>()+nodes(result),
        Ty::Struct(n)|Ty::NativeObject(n)|Ty::Enum(n)|Ty::Trait(n)=>n.arguments.iter().chain(n.associated_types.values()).map(nodes).sum(),
        Ty::Projection{receiver,interface,arguments,..}=>nodes(receiver)+interface.arguments.iter().chain(interface.associated_types.values()).chain(arguments).map(nodes).sum::<usize>(),
    }
}
fn checked(engine:&KagariEngine, condition:&str, growth:usize)->CheckedModule {
    if growth==0 { return engine.compile_source(SourceFile::new("probe.kgr",if condition=="trait" {TRAIT}else{"fn main()->i32{42}"})).unwrap(); }
    let insert=|name:&str,source:String| {
        let uri=format!("memory://{name}.kgr");
        engine.bind_module(&uri,ModuleIdentity{package:PackageId("probe".into()),path:vec![name.into()]}).unwrap();
        engine.set_source(&uri,source,SourceLayer::Base).unwrap()
    };
    insert("shared",match condition {
        "body" => "pub fn value() -> i32 { 43 }",
        "signature" => "pub fn value(input: i32) -> i32 { 43 + input }",
        _ => "pub fn value() -> i32 { 42 }",
    }.into());
    for i in 0..growth { insert(&format!("leaf{i}"),if condition=="signature" {"use probe::shared; pub fn read() -> i32 { shared::value(0) }"} else {"use probe::shared; pub fn read() -> i32 { shared::value() }"}.into()); }
    let imports=(0..growth).map(|i|format!("use probe::leaf{i};")).collect::<String>();
    let body=(0..growth).map(|i|format!("leaf{i}::read()")).collect::<Vec<_>>().join(" + ");
    let root=insert("root",format!("{imports} fn main() -> i32 {{ {body} }}"));
    engine.compile_snapshot(engine.source_snapshot(),root,&Default::default()).unwrap()
}
fn main(){
    for (label,growth) in [("minimal",0),("trait",0),("growth1",1),("growth8",8),("growth32",32)] {
        for sample in 0..5 {
            let t=Instant::now(); let engine=KagariEngine::default(); let engine_ms=millis(t);
            let t=Instant::now(); let input=checked(&engine,label,growth); let program=prepare(&engine,&input); let prepare_ms=millis(t);
            let t=Instant::now(); let context=Default::default(); let mut runtime=engine.runtime(context); let loaded=runtime.load_program(&program,Default::default()).unwrap(); let link_ms=millis(t);
            let t=Instant::now(); let result=runtime.execute(&loaded,ProgramEntry::Main,&[],&Default::default()).unwrap(); let first_ms=millis(t);
            let expected=42*if growth==0 {1}else{growth as i32}; assert_eq!(result.return_value.value(runtime.runtime().gc()).unwrap(),Value::I32(expected)); drop(result);
            let t=Instant::now(); let result=runtime.execute(&loaded,ProgramEntry::Main,&[],&Default::default()).unwrap(); let repeat_ms=millis(t); drop(result);
            let artifact=engine.EMIT_METHOD(&input,Default::default()).unwrap();
            let bytes=artifact.records().to_bytes(artifact.definitions()).unwrap();
            let t=Instant::now(); let external=PreparedProgram::from_artifact(BytecodeArtifact::from_bytes(&bytes).unwrap(),&Default::default(),&Default::default()).unwrap();let external_prepare_ms=millis(t);
            let t=Instant::now(); let mut external_runtime=engine.runtime(Default::default());let external_loaded=external_runtime.load_program(&external,Default::default()).unwrap();let external_link_ms=millis(t);
            let result=external_runtime.execute(&external_loaded,ProgramEntry::Main,&[],&Default::default()).unwrap();assert_eq!(result.return_value.value(external_runtime.runtime().gc()).unwrap(),Value::I32(expected));drop(result);
            let mut functions=0;let mut instructions=0;let mut declarations=0;let mut obligations=0;let mut types=0;let mut max_nodes=0;
            for module in program.bytecode().modules(){
                declarations+=module.public_items.len()+module.trait_contracts.len()+module.native_declarations.len();types+=module.types.len();
                for item in &module.public_items {if let PublicItem::InterfaceTable(table)=item {obligations+=table.bounds.iter().map(|b|b.constraints.len()).sum::<usize>();}}
                for f in &module.functions {functions+=1;instructions+=f.instructions.len();for ty in f.metadata.semantic.params.values().chain(f.metadata.semantic.result.iter()).chain(f.metadata.semantic.slots.values()){max_nodes=max_nodes.max(nodes(ty));}}
            }
            let t=Instant::now();let retained_input=checked(&engine,label,growth);let retained=prepare(&engine,&retained_input);let retained_prepare_ms=millis(t);drop(retained);
            if growth==8 {
                for edit in ["body","signature"] {
                    let t=Instant::now();let input=checked(&engine,edit,growth);let changed=prepare(&engine,&input);let edit_ms=millis(t);
                    let mut runtime=engine.runtime(Default::default());let loaded=runtime.load_program(&changed,Default::default()).unwrap();let result=runtime.execute(&loaded,ProgramEntry::Main,&[],&Default::default()).unwrap();assert_eq!(result.return_value.value(runtime.runtime().gc()).unwrap(),Value::I32(43*growth as i32));
                    println!("{{\"label\":\"edit-{edit}\",\"sample\":{sample},\"prepare_ms\":{edit_ms}}}");
                }
            }
            println!("{{\"label\":\"{label}\",\"sample\":{sample},\"engine_ms\":{engine_ms},\"prepare_ms\":{prepare_ms},\"link_ms\":{link_ms},\"first_ms\":{first_ms},\"repeat_ms\":{repeat_ms},\"external_prepare_ms\":{external_prepare_ms},\"external_link_ms\":{external_link_ms},\"retained_prepare_ms\":{retained_prepare_ms},\"modules\":{},\"functions\":{functions},\"instructions\":{instructions},\"declarations\":{declarations},\"table_constraints\":{obligations},\"physical_type_records\":{types},\"max_semantic_type_nodes\":{max_nodes}}}",program.bytecode().modules().len());
        }
    }
}

